steps.text:
Below is a minimal **Express .js** API that lets you manage a simple list of {{p:entity}} stored only in memory.  
It supports the usual CRUD operations (create, read, update, delete) and demonstrates basic error handling and JSON body parsing.

```js
// server.js
const express = require('express');
const app = express();
const port = 3000;

// ------------------------------------------------------------------
// In‑memory store
// ------------------------------------------------------------------
// Each task is an object: { id: number, title: string, completed: boolean }
let {{p:entity}} = [];
let nextId = 1;

// ------------------------------------------------------------------
// Middleware
// ------------------------------------------------------------------
app.use(express.json()); // parse JSON bodies

// ------------------------------------------------------------------
// Routes
// ------------------------------------------------------------------

// GET /{{p:entity}}
// Return the full list of {{p:entity}}
app.get('/{{p:entity}}', (req, res) => {
  res.json({{p:entity}});
});

// GET /{{p:entity}}/:id
// Return a single task by its id
app.get('/{{p:entity}}/:id', (req, res) => {
  const id = Number(req.params.id);
  const task = {{p:entity}}.find(t => t.id === id);

  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }
  res.json(task);
});

// POST /{{p:entity}}
// Create a new task. Body must contain a "title" field.
app.post('/{{p:entity}}', (req, res) => {
  const { title } = req.body;

  if (!title || typeof title !== 'string') {
    return res.status(400).json({ error: 'Invalid or missing "title"' });
  }

  const newTask = {
    id: nextId++,
    title: title.trim(),
    completed: false,
  };
  {{p:entity}}.push(newTask);
  res.status(201).json(newTask);
});

// PUT /{{p:entity}}/:id
// Replace an existing task (title & completed)
app.put('/{{p:entity}}/:id', (req, res) => {
  const id = Number(req.params.id);
  const taskIndex = {{p:entity}}.findIndex(t => t.id === id);

  if (taskIndex === -1) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const { title, completed } = req.body;
  if (typeof title !== 'string' || typeof completed !== 'boolean') {
    return res
      .status(400)
      .json({ error: '"title" must be string and "completed" must be boolean' });
  }

  const updatedTask = { id, title: title.trim(), completed };
  {{p:entity}}[taskIndex] = updatedTask;
  res.json(updatedTask);
});

// PATCH /{{p:entity}}/:id
// Partially update a task (e.g. toggle completed)
app.patch('/{{p:entity}}/:id', (req, res) => {
  const id = Number(req.params.id);
  const task = {{p:entity}}.find(t => t.id === id);

  if (!task) {
    return res.status(404).json({ error: 'Task not found' });
  }

  const { title, completed } = req.body;
  if (title !== undefined) {
    if (typeof title !== 'string') {
      return res.status(400).json({ error: '"title" must be a string' });
    }
    task.title = title.trim();
  }
  if (completed !== undefined) {
    if (typeof completed !== 'boolean') {
      return res.status(400).json({ error: '"completed" must be a boolean' });
    }
    task.completed = completed;
  }

  res.json(task);
});

// DELETE /{{p:entity}}/:id
// Remove a task from the store
app.delete('/{{p:entity}}/:id', (req, res) => {
  const id = Number(req.params.id);
  const initialLength = {{p:entity}}.length;
  {{p:entity}} = {{p:entity}}.filter(t => t.id !== id);

  if ({{p:entity}}.length === initialLength) {
    return res.status(404).json({ error: 'Task not found' });
  }

  res.status(204).send(); // No Content
});

// ------------------------------------------------------------------
// Start the server
// ------------------------------------------------------------------
app.listen(port, () => {
  console.log(`Task API listening at http://localhost:${port}`);
});
```

### How to run

1. **Create a project folder** and `cd` into it.  
2. Initialise npm and install Express:

   ```bash
   npm init -y
   npm install express
   ```

3. Save the code above as `server.js` in that folder.  
4. Start the API:

   ```bash
   node server.js
   ```

   You should see:

   ```
   Task API listening at http://localhost:3000
   ```

### Quick test with `curl`

```bash
# Create a task
curl -X POST -H "Content-Type: application/json" \
     -d '{"title":"Buy milk"}' http://localhost:3000/{{p:entity}}

# List all {{p:entity}}
curl http://localhost:3000/{{p:entity}}

# Mark task 1 as completed (partial update)
curl -X PATCH -H "Content-Type: application/json" \
     -d '{"completed":true}' http://localhost:3000/{{p:entity}}/1

# Delete task 1
curl -X DELETE http://localhost:3000/{{p:entity}}/1
```

Because the store lives only in memory, all data disappears when the process stops—perfect for prototyping, tests, or teaching the basics of a RESTful API.
